#!/usr/bin/env node
/**
 * build-routing-tree.mjs — compile routing-rules.md (+ taxonomy.md anchors)
 * into a flat routing-tree.json that the researcher agent can read in one shot
 * instead of sequentially grepping markdown.
 *
 * Generated by dealbreaker-v2 + meta-audit (2026-05-18).
 *
 * Output schema:
 * {
 *   "version": "1.0",
 *   "generated_at": "<ISO>",
 *   "source_files": [
 *     { "path": "routing-rules.md", "sha256": "..." },
 *     { "path": "taxonomy.md", "sha256": "..." }
 *   ],
 *   "tasks": [
 *     {
 *       "task": "Deep web research with citations",
 *       "primary": "perplexity/sonar-deep-research",
 *       "primary_note": "BrowseComp 90.1%",
 *       "backup": "openai/gpt-5-5-pro",
 *       "backup_note": "...",
 *       "avoid": "anthropic/claude-opus-4-7",
 *       "avoid_note": "BrowseComp 79.3%",
 *       "section_anchor": "Research + grounding"
 *     },
 *     ...
 *   ],
 *   "capability_axes": [...from taxonomy.md...],
 *   "operational_callouts": [
 *     { "header": "API constraint — budget_tokens routing rule", "body": "..." }
 *   ]
 * }
 *
 * Usage:
 *   node ~/Documents/council-os/scripts/build-routing-tree.mjs
 *
 * The researcher agent should call this BEFORE attempting any routing decision.
 * If routing-tree.json is older than 30 days OR routing-rules.md mtime is
 * newer than routing-tree.json, regenerate.
 */

import { readFileSync, writeFileSync, statSync } from 'node:fs';
import { createHash } from 'node:crypto';

const KB_DIR = '/Users/mitchellwilliams/Documents/council-os';
const ROUTING_RULES = `${KB_DIR}/routing-rules.md`;
const TAXONOMY = `${KB_DIR}/taxonomy.md`;
const OUT = `${KB_DIR}/routing-tree.json`;

function sha256(content) {
  return createHash('sha256').update(content).digest('hex').slice(0, 16);
}

function readWithSha(path) {
  const content = readFileSync(path, 'utf-8');
  return { content, sha: sha256(content), path };
}

// ─────────────────────────────────────────────────────────────────────────
// Parse the quick-reference matrix table in routing-rules.md
// ─────────────────────────────────────────────────────────────────────────

function parseMatrix(routingContent) {
  const lines = routingContent.split('\n');
  const tasks = [];
  let inMatrix = false;
  let currentSection = 'top-level';

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    // Track section context
    const sectionMatch = line.match(/^##\s+(.+)$/);
    if (sectionMatch && !sectionMatch[1].startsWith('Quick-reference matrix')) {
      currentSection = sectionMatch[1].trim();
    }
    if (line.includes('## Quick-reference matrix')) {
      inMatrix = true;
      continue;
    }
    if (inMatrix && line.trim().startsWith('---')) {
      inMatrix = false;
      continue;
    }
    if (inMatrix && line.trim().startsWith('|')) {
      // Skip header and separator rows
      if (line.includes('Task family') || line.match(/^\|\s*-+/)) continue;
      const cells = line.split('|').slice(1, -1).map(c => c.trim());
      if (cells.length < 4) continue;
      const [task, primary, backup, avoid] = cells;
      const parseSlot = (s) => {
        if (!s || s === '—' || s === '(none)') return { slot: null, note: null };
        const m = s.match(/^([^\s(]+)(?:\s+\((.+)\))?$/);
        if (m) return { slot: m[1], note: m[2] || null };
        return { slot: s, note: null };
      };
      tasks.push({
        task: task.replace(/\*\*/g, '').trim(),
        primary: parseSlot(primary),
        backup: parseSlot(backup),
        avoid: parseSlot(avoid),
        section_anchor: currentSection,
      });
    }
  }
  return tasks;
}

// ─────────────────────────────────────────────────────────────────────────
// Parse operational callouts (blockquotes with constraints)
// ─────────────────────────────────────────────────────────────────────────

function parseCallouts(routingContent) {
  const callouts = [];
  const blockPattern = />\s+\*\*([^*]+)\*\*:?\s*\n((?:>\s+[^\n]*\n?)+)/g;
  let m;
  while ((m = blockPattern.exec(routingContent)) !== null) {
    callouts.push({
      header: m[1].trim(),
      body: m[2].replace(/^>\s?/gm, '').trim(),
    });
  }
  return callouts;
}

// ─────────────────────────────────────────────────────────────────────────
// Parse taxonomy capability axes
// ─────────────────────────────────────────────────────────────────────────

function parseTaxonomy(taxonomyContent) {
  const axes = [];
  const lines = taxonomyContent.split('\n');
  for (const line of lines) {
    const m = line.match(/^-\s+`(\d+-[a-z0-9-]+)\.md`\s+—\s+(.+)$/);
    if (m) {
      axes.push({ chunk_id: m[1], description: m[2].trim() });
    }
  }
  return axes;
}

// ─────────────────────────────────────────────────────────────────────────
// Main
// ─────────────────────────────────────────────────────────────────────────

const routing = readWithSha(ROUTING_RULES);
const taxonomy = readWithSha(TAXONOMY);

const tasks = parseMatrix(routing.content);
const operational_callouts = parseCallouts(routing.content);
const capability_axes = parseTaxonomy(taxonomy.content);

const tree = {
  version: '1.0',
  generated_at: new Date().toISOString(),
  source_files: [
    { path: 'routing-rules.md', sha256: routing.sha, mtime: statSync(ROUTING_RULES).mtime.toISOString() },
    { path: 'taxonomy.md', sha256: taxonomy.sha, mtime: statSync(TAXONOMY).mtime.toISOString() },
  ],
  task_count: tasks.length,
  capability_axis_count: capability_axes.length,
  operational_callout_count: operational_callouts.length,
  tasks,
  capability_axes,
  operational_callouts,
  usage_note: 'Researcher agent should consume this for Phase 0.5 fast routing lookup. If mtime is older than 30 days, regenerate by running this script.',
};

writeFileSync(OUT, JSON.stringify(tree, null, 2), 'utf-8');
console.log(`[routing-tree] wrote ${tasks.length} tasks + ${capability_axes.length} axes + ${operational_callouts.length} callouts to ${OUT}`);
console.log(`[routing-tree] source SHAs: routing-rules=${routing.sha}, taxonomy=${taxonomy.sha}`);
